class Solution {
public:
    int maxSubarrays(vector<int>& nums) {
        int total = -1;
        for (int x : nums) total &= x;
        if (total > 0) return 1;
        int ans = 0, curr = -1;
        for (int x : nums) {
            curr &= x;
            if (curr == 0) {
                ans++;
                curr = -1;
            }
        }
        return ans;
    }
};

