var maxSubarrays = function(nums) {
    let total = -1;
    for (const x of nums) total &= x;
    if (total > 0) return 1;
    let ans = 0, curr = -1;
    for (const x of nums) {
        curr &= x;
        if (curr === 0) {
            ans++;
            curr = -1;
        }
    }
    return ans;
};
